class Solution { long long cost(long long target,int n,long long sum,long long minimum,int cost1,int cost2){long long total=target*n-sum,maxDeficit=target-minimum;long long pairs=min(total/2,total-maxDeficit);return pairs*cost2+(total-2*pairs)*cost1;}public:int minCostToEqualizeArray(vector<int>& nums,int cost1,int cost2){long long sum=accumulate(nums.begin(),nums.end(),0LL),minimum=*min_element(nums.begin(),nums.end()),maximum=*max_element(nums.begin(),nums.end());const long long mod=1000000007;int n=nums.size();if(n<=2||2LL*cost1<=cost2)return (maximum*n-sum)*cost1%mod;long long balance=(sum-2*minimum+n-3)/(n-2),best=LLONG_MAX;for(int delta=0;delta<=3;++delta)best=min(best,cost(maximum+delta,n,sum,minimum,cost1,cost2));for(int delta=-3;delta<=3;++delta){long long target=balance+delta;if(target>=maximum)best=min(best,cost(target,n,sum,minimum,cost1,cost2));}return best%mod;} };
